def get_tool(tool_name, **kwargs):
    from core.tool import Tool
    import json
    if tool_name == 'list-all':
        return ', '.join(Tool.list_all())
    else:
        tool = Tool.get(tool_name)
        if tool:
            properties = {}
            for p_name, p_details in tool.params.items():
                properties[p_name] = {
                    'type': p_details.get('type', 'string'),
                    'description': p_details.get('description', '')
                }
            return f"Tool Name: {tool.name}\nDescription: {tool.description}\nParameters: {json.dumps(properties)}"
        else:
            return f"Error: Tool '{tool_name}' not found."
